with content as (
  select * from jsonb_to_recordset($content$[
    {"level":"A1","title":"Amina Wants to Sew","body":"Amina likes clothes and colours. She wants to make dresses. This is her dream. She has a small notebook. She draws a dress in it.\n\nAmina does not have a sewing machine. She has a needle, thread and old cloth. Her aunt knows how to sew. She shows Amina how to make a straight line.\n\nAt first, Amina's lines are not straight. She is sad, but she tries again. She practises for ten minutes after school. She uses small pieces of cloth.\n\nAfter one month, Amina makes a small bag. She gives it to her little sister. Her sister smiles and uses the bag for her pencils.\n\nAmina still wants to make dresses. She knows that her dream needs time. Today she can sew a bag. Tomorrow she can learn something new.","summary_fr":"Amina rêve de coudre des robes. Elle commence avec une aiguille, du fil et de vieux tissus, s'entraîne chaque jour et fabrique un petit sac.","translation_fr":"Amina aime les vêtements et les couleurs. Elle veut fabriquer des robes. C'est son rêve. Elle a un petit carnet. Elle y dessine une robe.\n\nAmina n'a pas de machine à coudre. Elle a une aiguille, du fil et un vieux tissu. Sa tante sait coudre. Elle montre à Amina comment faire une ligne droite.\n\nAu début, les lignes d'Amina ne sont pas droites. Elle est triste, mais elle essaie encore. Elle s'entraîne pendant dix minutes après l'école. Elle utilise de petits morceaux de tissu.\n\nAprès un mois, Amina fabrique un petit sac. Elle l'offre à sa petite sœur. Sa sœur sourit et utilise le sac pour ses crayons.\n\nAmina veut toujours fabriquer des robes. Elle sait que son rêve demande du temps. Aujourd'hui, elle sait coudre un sac. Demain, elle pourra apprendre quelque chose de nouveau.","knowledge_point":"L'apprenant découvre qu'un rêve peut commencer par un petit apprentissage concret avec les moyens disponibles.","vocabulary":[{"word":"dream","part_of_speech":"noun","translation_fr":"rêve","definition":"Something you hope to do or have.","example":"Her dream is to make dresses."},{"word":"sew","part_of_speech":"verb","translation_fr":"coudre","definition":"To join cloth with a needle and thread.","example":"Her aunt knows how to sew."},{"word":"needle","part_of_speech":"noun","translation_fr":"aiguille","definition":"A small thin tool used for sewing.","example":"She has a needle and thread."},{"word":"thread","part_of_speech":"noun","translation_fr":"fil","definition":"A long thin material used for sewing.","example":"The thread is blue."},{"word":"cloth","part_of_speech":"noun","translation_fr":"tissu","definition":"Material used to make clothes and other things.","example":"She uses old cloth."},{"word":"straight","part_of_speech":"adjective","translation_fr":"droit","definition":"Without a curve or bend.","example":"She tries to sew a straight line."},{"word":"practise","part_of_speech":"verb","translation_fr":"s'entraîner","definition":"To do something regularly to improve.","example":"She practises after school."},{"word":"still","part_of_speech":"adverb","translation_fr":"toujours, encore","definition":"Continuing to be true.","example":"Amina still wants to make dresses."}],"questions":[{"type":"mcq","question":"What does Amina want to make?","options":["Dresses","Shoes","Books","Bags only"],"answer":"Dresses","explanation_fr":"Amina rêve de fabriquer des robes."},{"type":"mcq","question":"What does she draw in her notebook?","options":["A dress","A house","A bag","A school"],"answer":"A dress","explanation_fr":"Elle dessine une robe dans son carnet."},{"type":"mcq","question":"Who shows Amina how to sew?","options":["Her aunt","Her sister","Her teacher","Her friend"],"answer":"Her aunt","explanation_fr":"Sa tante sait coudre et lui montre."},{"type":"mcq","question":"How long does she practise after school?","options":["Ten minutes","One hour","Two hours","All night"],"answer":"Ten minutes","explanation_fr":"Elle s'entraîne dix minutes après l'école."},{"type":"mcq","question":"What does she make after one month?","options":["A small bag","A long dress","A new machine","A notebook"],"answer":"A small bag","explanation_fr":"Elle fabrique un petit sac après un mois."},{"type":"mcq","question":"Who receives the bag?","options":["Her little sister","Her aunt","Her teacher","Her mother"],"answer":"Her little sister","explanation_fr":"Amina offre le sac à sa petite sœur."},{"type":"mcq","question":"What does her sister put in the bag?","options":["Her pencils","Her clothes","Her books","Her food"],"answer":"Her pencils","explanation_fr":"Elle utilise le sac pour ses crayons."},{"type":"true_false","question":"Amina has a sewing machine at the beginning.","options":["True","False"],"answer":"False","explanation_fr":"Elle commence sans machine à coudre."},{"type":"true_false","question":"Amina understands that her dream needs time.","options":["True","False"],"answer":"True","explanation_fr":"Le dernier paragraphe exprime clairement cette idée."},{"type":"open","question":"What small first step can you take towards a dream?","options":[],"answer":"I can learn one basic skill, practise it for ten minutes and make something small.","explanation_fr":"La réponse doit proposer un premier pas simple et concret."}],"grammar":[{"point":"Want to plus verb","explanation_fr":"Want to suivi d'une base verbale exprime un souhait ou un objectif.","example":"She wants to make dresses."},{"point":"Can for present ability","explanation_fr":"Can exprime ce qu'une personne sait ou peut faire maintenant.","example":"Today she can sew a bag."}],"discussion":["What is one of your dreams?","What basic skill do you need for it?","Who can help you take your first step?"]},
    {"level":"A2","title":"A Dream with a First Step","body":"Junior enjoys repairing radios and small electrical objects. He often watches a technician who works near his home. His dream is to have his own repair shop one day. At first, this dream seems far away because he has no shop and very little equipment.\n\nInstead of waiting, Junior writes down what he can do now. He can learn the names of common tools in English. He can practise repairing an old radio with guidance. He can also save a small amount when he earns money.\n\nHe chooses one goal for the month: learn to test a simple electrical problem safely. The technician shows him the basic steps and explains which tasks he should not attempt alone. Junior keeps a notebook of the problems he observes and the solutions he learns.\n\nAfter a month, he does not own a shop, but his dream is clearer. He has new knowledge, a notebook and a better idea of what to learn next.\n\nJunior discovers that a dream becomes less frightening when it has a first step. The first step does not complete the journey. It gives the journey a direction and helps you move from wishing to learning.","summary_fr":"Junior rêve d'ouvrir un atelier de réparation. Sans attendre d'avoir un local, il apprend avec un technicien, garde un carnet et choisit un objectif mensuel réaliste.","translation_fr":"Junior aime réparer les radios et les petits appareils électriques. Il observe souvent un technicien qui travaille près de chez lui. Son rêve est d'avoir un jour son propre atelier de réparation. Au début, ce rêve semble lointain parce qu'il n'a pas d'atelier et très peu de matériel.\n\nAu lieu d'attendre, Junior écrit ce qu'il peut faire maintenant. Il peut apprendre les noms des outils courants en anglais. Il peut s'entraîner à réparer une vieille radio avec de l'aide. Il peut aussi économiser une petite somme lorsqu'il gagne de l'argent.\n\nIl choisit un objectif pour le mois : apprendre à tester un problème électrique simple en toute sécurité. Le technicien lui montre les étapes de base et explique quelles tâches il ne doit pas tenter seul. Junior garde un carnet des problèmes observés et des solutions apprises.\n\nAprès un mois, il ne possède pas d'atelier, mais son rêve est plus clair. Il a de nouvelles connaissances, un carnet et une meilleure idée de ce qu'il doit apprendre ensuite.\n\nJunior découvre qu'un rêve fait moins peur lorsqu'il a un premier pas. Le premier pas ne termine pas le voyage. Il donne une direction au voyage et aide à passer du souhait à l'apprentissage.","knowledge_point":"L'apprenant apprend à transformer un rêve lointain en première étape réaliste, sûre et observable.","vocabulary":[{"word":"repair","part_of_speech":"verb","translation_fr":"réparer","definition":"To fix something that is broken.","example":"Junior repairs old radios."},{"word":"technician","part_of_speech":"noun","translation_fr":"technicien","definition":"A person with practical technical skills.","example":"A technician works near his home."},{"word":"equipment","part_of_speech":"noun","translation_fr":"matériel","definition":"The tools or objects needed for an activity.","example":"He has very little equipment."},{"word":"instead","part_of_speech":"adverb","translation_fr":"au lieu de cela","definition":"In place of another action.","example":"Instead of waiting, he writes a list."},{"word":"guidance","part_of_speech":"noun","translation_fr":"accompagnement","definition":"Help and advice from someone experienced.","example":"He practises with guidance."},{"word":"safely","part_of_speech":"adverb","translation_fr":"en toute sécurité","definition":"Without causing danger or harm.","example":"He learns to test a problem safely."},{"word":"attempt","part_of_speech":"verb","translation_fr":"tenter","definition":"To try to do something difficult.","example":"He should not attempt some tasks alone."},{"word":"frightening","part_of_speech":"adjective","translation_fr":"effrayant","definition":"Making you feel afraid.","example":"A clear dream is less frightening."}],"questions":[{"type":"mcq","question":"What is Junior's dream?","options":["To have his own repair shop","To become a driver","To sell clothes","To teach English"],"answer":"To have his own repair shop","explanation_fr":"Junior veut avoir son propre atelier de réparation."},{"type":"mcq","question":"Why does the dream seem far away?","options":["He has no shop and little equipment","He dislikes radios","He has no notebook","He cannot write goals"],"answer":"He has no shop and little equipment","explanation_fr":"Le manque de local et de matériel rend le rêve lointain."},{"type":"mcq","question":"What can Junior learn in English now?","options":["The names of common tools","How to own a building","Advanced mathematics","How to repair every machine"],"answer":"The names of common tools","explanation_fr":"Il peut commencer par apprendre le nom des outils courants."},{"type":"mcq","question":"What is his goal for the month?","options":["To test a simple electrical problem safely","To open a large shop","To buy every tool","To work without guidance"],"answer":"To test a simple electrical problem safely","explanation_fr":"C'est l'objectif mensuel précis qu'il choisit."},{"type":"mcq","question":"What does the technician explain?","options":["Which tasks Junior should not attempt alone","How to avoid all learning","Where to buy a shop immediately","Why notebooks are useless"],"answer":"Which tasks Junior should not attempt alone","explanation_fr":"Le technicien fixe des limites de sécurité."},{"type":"mcq","question":"What does Junior put in his notebook?","options":["Observed problems and learned solutions","Only prices of shops","Stories about travel","Lists of clothes"],"answer":"Observed problems and learned solutions","explanation_fr":"Le carnet contient les problèmes observés et leurs solutions."},{"type":"mcq","question":"What does the first step provide?","options":["Direction and a move towards learning","Immediate ownership of a shop","A guarantee of success","The end of the journey"],"answer":"Direction and a move towards learning","explanation_fr":"Le premier pas oriente et fait passer du souhait à l'apprentissage."},{"type":"true_false","question":"Junior owns a repair shop after one month.","options":["True","False"],"answer":"False","explanation_fr":"Il n'a pas encore d'atelier, mais il a progressé."},{"type":"true_false","question":"Junior chooses to act with the resources he has.","options":["True","False"],"answer":"True","explanation_fr":"Il apprend, s'entraîne avec aide et économise selon ses moyens."},{"type":"open","question":"What could you write on your own list of possible first steps?","options":[],"answer":"I can list one skill to learn, one person to ask for guidance and one small amount of time or money to use regularly.","explanation_fr":"La réponse doit proposer des actions immédiates et réalistes."}],"grammar":[{"point":"Gerund after prepositions","explanation_fr":"Après une préposition comme instead of, le verbe prend la forme en ing.","example":"Instead of waiting, Junior writes down what he can do."},{"point":"From wishing to learning","explanation_fr":"From... to... exprime un passage d'un état ou d'une action à un autre.","example":"It helps you move from wishing to learning."}],"discussion":["What dream would you like to make clearer?","Which resources do you already have?","Why can guidance make a first step safer?"]},
    {"level":"B1","title":"More Than a Nice Idea","body":"Many people have a dream they enjoy talking about. They imagine a different job, a successful project or a new skill. These images can give energy and hope. However, a dream becomes more useful when we ask what it requires in ordinary life.\n\nConsider Clarisse, who wants to become an event photographer. She enjoys taking pictures with her phone, but she has never photographed a large event. Her first thought is to buy an expensive camera. After speaking to an experienced photographer, she realises that equipment is only one part of the work. She also needs to understand light, communicate with clients and deliver photographs on time.\n\nClarisse chooses a small event at her community centre as a learning opportunity. She asks permission before taking pictures and prepares a simple plan. She lists the important moments, checks her phone battery and agrees on when she will share the photographs. The event does not make her a professional immediately, but it teaches her more than imagination alone.\n\nAfterwards, she reviews her work honestly. Some photographs are too dark, and a few important moments are missing. Instead of treating these problems as proof that her dream is impossible, she turns them into learning goals.\n\nA meaningful dream is not a perfect picture of the future. It is a direction that changes what you practise today. When imagination meets real experience, you discover both the pleasure of the work and the effort it requires.","summary_fr":"Clarisse veut devenir photographe d'événements. Elle teste son rêve lors d'une petite activité communautaire, observe ses difficultés et transforme les problèmes en objectifs d'apprentissage.","translation_fr":"Beaucoup de gens ont un rêve dont ils aiment parler. Ils imaginent un métier différent, un projet réussi ou une nouvelle compétence. Ces images peuvent donner de l'énergie et de l'espoir. Cependant, un rêve devient plus utile lorsqu'on se demande ce qu'il exige dans la vie ordinaire.\n\nPrenons Clarisse, qui veut devenir photographe d'événements. Elle aime prendre des photos avec son téléphone, mais elle n'a jamais photographié un grand événement. Sa première idée est d'acheter un appareil photo coûteux. Après avoir parlé à une photographe expérimentée, elle comprend que le matériel n'est qu'une partie du travail. Elle doit aussi comprendre la lumière, communiquer avec les clients et livrer les photos à temps.\n\nClarisse choisit un petit événement dans son centre communautaire comme occasion d'apprendre. Elle demande la permission avant de prendre des photos et prépare un plan simple. Elle note les moments importants, vérifie la batterie de son téléphone et convient du moment où elle partagera les photos. Cet événement ne fait pas d'elle une professionnelle immédiatement, mais il lui apprend plus que l'imagination seule.\n\nEnsuite, elle examine son travail honnêtement. Certaines photos sont trop sombres et quelques moments importants manquent. Au lieu de considérer ces problèmes comme la preuve que son rêve est impossible, elle les transforme en objectifs d'apprentissage.\n\nUn rêve significatif n'est pas une image parfaite du futur. C'est une direction qui change ce que vous pratiquez aujourd'hui. Quand l'imagination rencontre l'expérience réelle, vous découvrez à la fois le plaisir du travail et l'effort qu'il demande.","knowledge_point":"L'apprenant découvre qu'une expérience réelle permet de préciser un rêve et d'identifier les compétences à développer.","vocabulary":[{"word":"skill","part_of_speech":"noun","translation_fr":"compétence","definition":"The ability to do something well.","example":"Photography requires several skills."},{"word":"require","part_of_speech":"verb","translation_fr":"exiger, nécessiter","definition":"To need something.","example":"The work requires preparation."},{"word":"event","part_of_speech":"noun","translation_fr":"événement","definition":"An organised occasion or activity.","example":"She photographs a small event."},{"word":"realise","part_of_speech":"verb","translation_fr":"se rendre compte","definition":"To begin to understand something.","example":"She realises that equipment is only one part."},{"word":"deliver","part_of_speech":"verb","translation_fr":"livrer, remettre","definition":"To give completed work to someone.","example":"She must deliver photographs on time."},{"word":"permission","part_of_speech":"noun","translation_fr":"permission","definition":"Agreement that allows you to do something.","example":"She asks permission before taking pictures."},{"word":"missing","part_of_speech":"adjective","translation_fr":"manquant","definition":"Not present where it should be.","example":"A few important moments are missing."},{"word":"meaningful","part_of_speech":"adjective","translation_fr":"significatif","definition":"Having real value or purpose.","example":"A meaningful dream changes what you practise."}],"questions":[{"type":"mcq","question":"What job does Clarisse want?","options":["Event photographer","Camera seller","Community manager","English teacher"],"answer":"Event photographer","explanation_fr":"Clarisse veut devenir photographe d'événements."},{"type":"mcq","question":"What is her first thought?","options":["To buy an expensive camera","To stop taking pictures","To organise a concert","To move to another country"],"answer":"To buy an expensive camera","explanation_fr":"Elle pense d'abord acheter un appareil coûteux."},{"type":"mcq","question":"Which skill does she need besides understanding light?","options":["Communicating with clients","Repairing telephones","Designing buildings","Driving a bus"],"answer":"Communicating with clients","explanation_fr":"Le texte cite la communication avec les clients."},{"type":"mcq","question":"Where does she practise?","options":["At her community centre","At an international stadium","At a camera shop","At a school examination"],"answer":"At her community centre","explanation_fr":"Elle choisit un petit événement de son centre communautaire."},{"type":"mcq","question":"What does she check before the event?","options":["Her phone battery","Her new camera","The clients' houses","The weather in another country"],"answer":"Her phone battery","explanation_fr":"La vérification de la batterie fait partie de sa préparation."},{"type":"mcq","question":"What problem appears in her review?","options":["Some photographs are too dark","Every photograph is perfect","She has no phone","The event is cancelled"],"answer":"Some photographs are too dark","explanation_fr":"Elle constate que certaines photos sont trop sombres."},{"type":"mcq","question":"How does she respond to the problems?","options":["She turns them into learning goals","She abandons photography","She hides every photograph","She buys equipment without learning"],"answer":"She turns them into learning goals","explanation_fr":"Les difficultés deviennent des objectifs d'apprentissage."},{"type":"true_false","question":"One small event immediately makes Clarisse a professional.","options":["True","False"],"answer":"False","explanation_fr":"Le texte précise que cette expérience ne la rend pas immédiatement professionnelle."},{"type":"true_false","question":"A dream can guide what you practise today.","options":["True","False"],"answer":"True","explanation_fr":"C'est l'idée principale de la conclusion."},{"type":"open","question":"What real experience could help you understand one of your dreams better?","options":[],"answer":"I could volunteer for a small related activity, observe the skills required and review what I need to learn.","explanation_fr":"La réponse doit proposer une expérience accessible et un enseignement à en tirer."}],"grammar":[{"point":"Present perfect for life experience","explanation_fr":"Le present perfect indique une expérience sans date passée précise.","example":"She has never photographed a large event."},{"point":"Instead of treating","explanation_fr":"Instead of suivi d'un gérondif présente une réaction choisie à la place d'une autre.","example":"Instead of treating these problems as proof, she turns them into goals."}],"discussion":["Which part of your dream have you never tested in real life?","Why can imagination hide important skills?","How can a mistake become a learning goal?"]},
    {"level":"B2","title":"Dreams Need a Place in Real Life","body":"A dream often begins as an attractive picture of the future. The picture matters because it gives emotional energy, but it can also hide the ordinary activities on which achievement depends. Someone who dreams of running a business may imagine independence and recognition while overlooking customer service, record keeping and repeated disappointment.\n\nThis does not make the dream unrealistic. It means that the dream needs to encounter reality before it can guide decisions. One way to create that encounter is through a small, reversible experiment. A person interested in baking could prepare orders for a few neighbours rather than immediately renting a shop. The experiment would test not only the quality of the cakes, but also pricing, delivery, time management and the baker's enjoyment of the routine.\n\nSuch an experiment should answer a specific question. If the question is simply whether the dream feels exciting, imagination can already provide the answer. A better question might be whether customers will order again at a price that covers ingredients and time. The result may support the dream, change its form or reveal that another direction is preferable. All three outcomes are useful.\n\nDreams also need boundaries. Pursuing a goal should not require ignoring health, family responsibilities or every other interest. A sustainable direction leaves room for rest and revision. Otherwise, the dream can become a demand for permanent sacrifice rather than a source of purpose.\n\nThe aim is not to kill imagination with practical details. It is to give imagination somewhere to stand. When a dream includes real tasks, honest feedback and reasonable limits, it becomes less like an escape from life and more like a way of shaping it.","summary_fr":"Un rêve gagne à être testé par une petite expérience réversible, une question précise et des limites raisonnables. La réalité peut confirmer, transformer ou réorienter le projet.","translation_fr":"Un rêve commence souvent comme une image séduisante du futur. Cette image compte parce qu'elle donne une énergie émotionnelle, mais elle peut aussi cacher les activités ordinaires dont dépend la réussite. Quelqu'un qui rêve de diriger une entreprise peut imaginer l'indépendance et la reconnaissance tout en négligeant le service client, la tenue des registres et les déceptions répétées.\n\nCela ne rend pas le rêve irréaliste. Cela signifie que le rêve doit rencontrer la réalité avant de pouvoir guider les décisions. Une façon de créer cette rencontre est de mener une petite expérience réversible. Une personne intéressée par la pâtisserie pourrait préparer des commandes pour quelques voisins plutôt que de louer immédiatement une boutique. L'expérience testerait non seulement la qualité des gâteaux, mais aussi les prix, la livraison, la gestion du temps et le plaisir de la routine.\n\nUne telle expérience doit répondre à une question précise. Si la question est simplement de savoir si le rêve est enthousiasmant, l'imagination peut déjà répondre. Une meilleure question serait de savoir si les clients commanderont à nouveau à un prix qui couvre les ingrédients et le temps. Le résultat peut soutenir le rêve, changer sa forme ou révéler qu'une autre direction est préférable. Les trois résultats sont utiles.\n\nLes rêves ont aussi besoin de limites. Poursuivre un objectif ne devrait pas exiger de négliger la santé, les responsabilités familiales ou tout autre centre d'intérêt. Une direction durable laisse de la place au repos et à la révision. Sinon, le rêve peut devenir une exigence de sacrifice permanent plutôt qu'une source de sens.\n\nLe but n'est pas de tuer l'imagination avec des détails pratiques. Il est de donner à l'imagination un point d'appui. Quand un rêve comprend des tâches réelles, des retours honnêtes et des limites raisonnables, il ressemble moins à une fuite hors de la vie et davantage à une façon de la construire.","knowledge_point":"L'apprenant apprend à tester une ambition avec une expérience réversible, une question mesurable et des limites durables.","vocabulary":[{"word":"overlook","part_of_speech":"verb","translation_fr":"négliger, oublier","definition":"To fail to notice or consider something.","example":"He overlooks record keeping."},{"word":"encounter","part_of_speech":"noun","translation_fr":"rencontre","definition":"An occasion when something meets or experiences something else.","example":"The dream needs an encounter with reality."},{"word":"reversible","part_of_speech":"adjective","translation_fr":"réversible","definition":"Possible to stop or change without permanent effects.","example":"Start with a reversible experiment."},{"word":"pricing","part_of_speech":"noun","translation_fr":"fixation des prix","definition":"The process of deciding how much to charge.","example":"The experiment tests pricing."},{"word":"cover","part_of_speech":"verb","translation_fr":"couvrir","definition":"To be enough to pay for a cost.","example":"The price should cover ingredients and time."},{"word":"boundary","part_of_speech":"noun","translation_fr":"limite","definition":"A limit that protects what is acceptable.","example":"Dreams need boundaries."},{"word":"sustainable","part_of_speech":"adjective","translation_fr":"durable","definition":"Able to continue without unacceptable harm.","example":"A sustainable direction leaves room for rest."},{"word":"revision","part_of_speech":"noun","translation_fr":"révision, réajustement","definition":"The process of changing something after review.","example":"Leave room for revision."}],"questions":[{"type":"mcq","question":"What can an attractive picture of the future hide?","options":["Ordinary activities required for achievement","All emotional energy","The value of feedback","Every possible direction"],"answer":"Ordinary activities required for achievement","explanation_fr":"L'image du futur peut cacher les tâches ordinaires nécessaires."},{"type":"mcq","question":"Which business tasks are mentioned?","options":["Customer service and record keeping","Only recognition and independence","Travel and photography","Sewing and gardening"],"answer":"Customer service and record keeping","explanation_fr":"Le service client et la tenue des registres sont cités."},{"type":"mcq","question":"Why is preparing orders for neighbours useful?","options":["It tests several parts of the activity on a small scale","It immediately proves the need for a shop","It removes the need for pricing","It guarantees repeated orders"],"answer":"It tests several parts of the activity on a small scale","explanation_fr":"Cette expérience teste produit, prix, livraison, temps et motivation."},{"type":"mcq","question":"What makes an experimental question better?","options":["It can be answered with observable results","It only asks whether the dream is exciting","It assumes success before starting","It avoids all practical details"],"answer":"It can be answered with observable results","explanation_fr":"Une bonne question porte sur des comportements et des coûts observables."},{"type":"mcq","question":"Which outcome is considered useful?","options":["Supporting, changing or rejecting the original direction","Only confirming the original dream","Only increasing the scale","Ignoring disappointing evidence"],"answer":"Supporting, changing or rejecting the original direction","explanation_fr":"Les trois types de résultats apportent une information utile."},{"type":"mcq","question":"Why do dreams need boundaries?","options":["To protect health, responsibilities and room for revision","To make sacrifice permanent","To eliminate every other interest","To avoid all feedback"],"answer":"To protect health, responsibilities and room for revision","explanation_fr":"Les limites rendent la poursuite du rêve durable."},{"type":"mcq","question":"What is the author's final position?","options":["Practical details give imagination a foundation","Imagination should be abandoned","Every dream should remain small","Feedback is less useful than excitement"],"answer":"Practical details give imagination a foundation","explanation_fr":"Le texte veut donner à l'imagination un point d'appui réel."},{"type":"true_false","question":"A reversible experiment must produce complete success to be useful.","options":["True","False"],"answer":"False","explanation_fr":"Même un résultat qui modifie ou réoriente le rêve est utile."},{"type":"true_false","question":"A sustainable goal leaves room for rest.","options":["True","False"],"answer":"True","explanation_fr":"Le repos fait partie des limites nécessaires."},{"type":"open","question":"Design a reversible experiment for one dream and state its question.","options":[],"answer":"I could complete one small paid project for a real user and ask whether the result, time and price make a repeated service realistic.","explanation_fr":"La réponse doit proposer un test limité et une question observable."}],"grammar":[{"point":"Rather than for preference","explanation_fr":"Rather than suivi d'une base verbale oppose l'option choisie à une autre option.","example":"Prepare orders for neighbours rather than immediately renting a shop."},{"point":"Whether for a testable alternative","explanation_fr":"Whether introduit une question indirecte dont la réponse peut être oui ou non.","example":"Ask whether customers will order again."}],"discussion":["What ordinary work might your dream hide?","Which experiment could test it without a large risk?","What boundary would make your goal sustainable?"]},
    {"level":"C1","title":"The Difference Between Fantasy and Direction","body":"Fantasy and ambition can use exactly the same images. Both may involve a thriving business, a published book or a respected profession. The distinction lies not in the size of the vision but in its relationship to action. Fantasy offers emotional refuge without demanding a change in conduct. Direction exposes the vision to evidence, constraints and choice.\n\nThis distinction should not be used to dismiss imagination. Before anything is built, it must be conceivable. Imagining a future can reveal what a person values and provide the motivation to endure tedious preparation. Yet imagination becomes unreliable when it supplies only the rewarding scenes: the opening ceremony, the appreciative audience, the finished product. A viable ambition must also accommodate the unphotographed scenes, including repetition, negotiation and revision.\n\nOne practical test is to ask what the dream obliges you to learn. A meaningful direction produces questions that can be investigated. What do potential users actually need? Which competence is currently limiting the project? What commitment would be incompatible with existing responsibilities? Such questions may make the dream less comfortable, but they make it more intelligent.\n\nAnother test concerns revisability. If every disappointing result is treated as an attack on identity, the dream becomes fragile. A person must either deny the evidence or abandon the entire vision. By contrast, someone who treats the dream as a direction can modify its scale, timing or form without concluding that their life has lost meaning.\n\nThere is also an ethical dimension. A future worth pursuing should not depend entirely on exploiting other people or damaging the foundations of one's own wellbeing. Ambition is not automatically noble merely because it is difficult. Its value depends partly on what it asks of others and what it gradually makes of us.\n\nThe purpose of examining a dream is therefore neither cynicism nor blind optimism. It is to transform an alluring image into a responsible direction: vivid enough to inspire, concrete enough to test and flexible enough to survive contact with reality.","summary_fr":"Un rêve devient une direction lorsqu'il accepte les faits, les contraintes, l'apprentissage et la révision. L'imagination reste essentielle, mais elle doit aussi intégrer les responsabilités et les tâches invisibles.","translation_fr":"Le fantasme et l'ambition peuvent utiliser exactement les mêmes images. Tous deux peuvent impliquer une entreprise prospère, un livre publié ou une profession respectée. La distinction ne réside pas dans la taille de la vision, mais dans sa relation à l'action. Le fantasme offre un refuge émotionnel sans exiger de changement de conduite. La direction expose la vision aux preuves, aux contraintes et aux choix.\n\nCette distinction ne doit pas servir à rejeter l'imagination. Avant qu'une chose soit construite, elle doit pouvoir être conçue. Imaginer un futur peut révéler ce qu'une personne valorise et donner la motivation nécessaire pour supporter une préparation fastidieuse. Pourtant, l'imagination devient peu fiable lorsqu'elle fournit seulement les scènes gratifiantes : la cérémonie d'ouverture, le public reconnaissant, le produit fini. Une ambition viable doit aussi accepter les scènes non photographiées, notamment la répétition, la négociation et la révision.\n\nUn test pratique consiste à demander ce que le rêve oblige à apprendre. Une direction significative produit des questions qui peuvent être examinées. De quoi les utilisateurs potentiels ont-ils réellement besoin ? Quelle compétence limite actuellement le projet ? Quel engagement serait incompatible avec les responsabilités existantes ? Ces questions peuvent rendre le rêve moins confortable, mais elles le rendent plus intelligent.\n\nUn autre test concerne la capacité de révision. Si chaque résultat décevant est traité comme une attaque contre l'identité, le rêve devient fragile. La personne doit soit nier les faits, soit abandonner toute la vision. À l'inverse, celui qui traite le rêve comme une direction peut modifier son ampleur, son calendrier ou sa forme sans conclure que sa vie a perdu son sens.\n\nIl existe aussi une dimension éthique. Un avenir digne d'être poursuivi ne devrait pas dépendre entièrement de l'exploitation des autres ou de la destruction des fondements de son propre bien-être. L'ambition n'est pas automatiquement noble simplement parce qu'elle est difficile. Sa valeur dépend en partie de ce qu'elle demande aux autres et de ce qu'elle fait progressivement de nous.\n\nExaminer un rêve n'a donc pour but ni le cynisme ni l'optimisme aveugle. Il s'agit de transformer une image séduisante en une direction responsable : assez vivante pour inspirer, assez concrète pour être testée et assez flexible pour survivre au contact avec la réalité.","knowledge_point":"L'apprenant distingue l'évasion imaginative d'une ambition responsable, vérifiable, révisable et attentive à ses effets sur soi et sur les autres.","vocabulary":[{"word":"refuge","part_of_speech":"noun","translation_fr":"refuge","definition":"A place or state that provides protection or escape.","example":"Fantasy can offer emotional refuge."},{"word":"conceivable","part_of_speech":"adjective","translation_fr":"concevable","definition":"Possible to imagine or think about.","example":"Before it is built, it must be conceivable."},{"word":"tedious","part_of_speech":"adjective","translation_fr":"fastidieux","definition":"Long, repetitive and boring.","example":"Motivation helps us endure tedious preparation."},{"word":"viable","part_of_speech":"adjective","translation_fr":"viable","definition":"Capable of working successfully.","example":"A viable ambition includes ordinary work."},{"word":"revisability","part_of_speech":"noun","translation_fr":"capacité de révision","definition":"The quality of being open to change after new evidence.","example":"Revisability prevents a dream from becoming fragile."},{"word":"deny","part_of_speech":"verb","translation_fr":"nier","definition":"To refuse to accept that something is true.","example":"A person may deny disappointing evidence."},{"word":"exploit","part_of_speech":"verb","translation_fr":"exploiter","definition":"To use someone unfairly for personal benefit.","example":"A worthy future should not exploit others."},{"word":"alluring","part_of_speech":"adjective","translation_fr":"séduisant","definition":"Attractive and tempting.","example":"Turn an alluring image into a responsible direction."}],"questions":[{"type":"mcq","question":"What distinguishes fantasy from direction?","options":["Its relationship to action and evidence","The size of the imagined future","The presence of attractive images","The profession chosen"],"answer":"Its relationship to action and evidence","explanation_fr":"La distinction repose sur la relation à l'action, aux preuves et aux choix."},{"type":"mcq","question":"Why is imagination valuable?","options":["It reveals values and can motivate preparation","It guarantees a viable project","It removes tedious work","It supplies every practical answer"],"answer":"It reveals values and can motivate preparation","explanation_fr":"L'imagination aide à concevoir, valoriser et supporter la préparation."},{"type":"mcq","question":"Which scenes can imagination omit?","options":["Repetition, negotiation and revision","Opening ceremonies only","Finished products only","Appreciative audiences only"],"answer":"Repetition, negotiation and revision","explanation_fr":"Une ambition viable doit intégrer ces scènes moins visibles."},{"type":"mcq","question":"What does a meaningful direction produce?","options":["Questions that can be investigated","Only comfortable emotions","A refusal of all constraints","A fixed identity that cannot change"],"answer":"Questions that can be investigated","explanation_fr":"La direction transforme la vision en questions examinables."},{"type":"mcq","question":"Why does linking every result to identity make a dream fragile?","options":["Disappointment can force denial or total abandonment","It makes revision easier","It separates scale from meaning","It improves evidence"],"answer":"Disappointment can force denial or total abandonment","explanation_fr":"L'identité rigide empêche d'utiliser les résultats décevants pour réviser."},{"type":"mcq","question":"What can a person revise without losing meaning?","options":["Scale, timing or form","Values, evidence and every responsibility","Only the final celebration","Nothing under any circumstances"],"answer":"Scale, timing or form","explanation_fr":"Ces trois dimensions peuvent changer sans vider la vie de sens."},{"type":"mcq","question":"What does the ethical test examine?","options":["What ambition asks of others and makes of us","Whether ambition is difficult enough","How dramatic the vision appears","How quickly recognition arrives"],"answer":"What ambition asks of others and makes of us","explanation_fr":"La valeur morale dépend des effets sur les autres et sur soi."},{"type":"true_false","question":"The text argues that difficult ambitions are automatically noble.","options":["True","False"],"answer":"False","explanation_fr":"La difficulté seule ne donne pas une valeur morale à l'ambition."},{"type":"true_false","question":"A responsible direction should be concrete and flexible.","options":["True","False"],"answer":"True","explanation_fr":"La conclusion associe inspiration, testabilité et flexibilité."},{"type":"open","question":"Which question could make one of your dreams more intelligent and responsible?","options":[],"answer":"I can ask which competence I need, what the project requires from others and how I would revise it if evidence challenges my plan.","explanation_fr":"La réponse doit introduire une question concrète sur l'apprentissage, les contraintes ou les effets éthiques."}],"grammar":[{"point":"Neither nor for rejection","explanation_fr":"Neither... nor... relie deux options qui sont toutes deux rejetées.","example":"The purpose is neither cynicism nor blind optimism."},{"point":"Enough with adjectives","explanation_fr":"Enough se place après l'adjectif pour indiquer que le degré est suffisant.","example":"Vivid enough to inspire, concrete enough to test and flexible enough to survive."}],"discussion":["When does imagination support action, and when does it replace action?","Which part of a dream should remain flexible?","How can ambition affect other people responsibly?"]}
  ]$content$::jsonb) as x(
    level public.rw_level, title text, body text, summary_fr text, translation_fr text,
    knowledge_point text, vocabulary jsonb, questions jsonb, grammar jsonb, discussion jsonb
  )
)
insert into public.rw_lessons (
  session_id, level, title, body, word_count, summary_fr, translation_fr, knowledge_point,
  vocabulary, questions, grammar, discussion, mention, status, content_type, rights_status, published_at
)
select s.id, c.level, c.title, c.body,
  cardinality(regexp_split_to_array(btrim(c.body), '[[:space:]]+')),
  c.summary_fr, c.translation_fr, c.knowledge_point, c.vocabulary, c.questions,
  c.grammar, c.discussion, 'original', 'published', 'original text',
  'Texte original OpenDoorsClass', now()
from content c
join public.rw_weeks w on w.week_number = 4
join public.rw_sessions s on s.week_id = w.id and s.day_index = 1
on conflict (session_id, level) do update set
  title = excluded.title, body = excluded.body, word_count = excluded.word_count,
  summary_fr = excluded.summary_fr, translation_fr = excluded.translation_fr,
  knowledge_point = excluded.knowledge_point, vocabulary = excluded.vocabulary,
  questions = excluded.questions, grammar = excluded.grammar, discussion = excluded.discussion,
  mention = 'original', status = 'published', content_type = 'original text',
  rights_status = 'Texte original OpenDoorsClass', published_at = coalesce(rw_lessons.published_at, now())
where rw_lessons.status <> 'published';

do $$
declare invalid_count integer;
begin
  select count(*) into invalid_count from public.rw_lessons l
  join public.rw_sessions s on s.id=l.session_id join public.rw_weeks w on w.id=s.week_id
  where w.week_number=4 and s.day_index=1 and (l.status<>'published'
    or jsonb_array_length(l.questions)<>10 or jsonb_array_length(l.vocabulary)<8
    or jsonb_array_length(l.grammar)<>2 or jsonb_array_length(l.discussion)<>3
    or l.body='' or coalesce(l.translation_fr,'')='');
  if invalid_count<>0 then raise exception 'Validation impossible: % leçons incomplètes',invalid_count; end if;
end $$;